<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifications · Atlas</title><link rel="stylesheet" href="<?=esc(url_for('assets/app.css'))?>"></head><body class="standalone-with-nav"><?=standaloneSidebar($navGroups,'notifications',$admin,$org,$user,$location)?><main class="page-wrap standalone-workspace"><header class="page-header"><div><p class="eyebrow">WORKFORCE ALERTS</p><h1>Notifications</h1><p>Choose what reaches you and review recent activity.</p></div><form method="post"><?=Csrf::field()?><input type="hidden" name="action" value="mark_notifications_read"><button class="button secondary">Mark all read</button></form></header><?php if($notice):?><div class="page-flash success"><span>✓</span><?=esc($notice['message'])?></div><?php endif;?><section class="planning-grid"><article class="panel"><h2>Delivery preferences</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="save_notification_preferences"><?php foreach(['schedule_published'=>'Schedule published','schedule_changed'=>'My schedule changes','coverage_offers'=>'Coverage offers','request_decisions'=>'Request decisions','credential_reminders'=>'Credential reminders','in_app_enabled'=>'In-app notifications','email_enabled'=>'Email delivery'] as $key=>$label):?><label class="check-label"><input type="checkbox" name="<?=$key?>" value="1" <?=!empty($notificationPreferences[$key])?'checked':''?>><span><?=$label?></span></label><?php endforeach;?><button class="button primary">Save preferences</button></form></article><article class="panel span-2"><h2>Notification inbox</h2><?php foreach($notifications as $n):?><div class="planning-row"><span><strong><?=esc($n['title'])?></strong><small><?=esc($n['created_at'])?></small><p><?=esc($n['body'])?></p></span><b class="state-pill <?=$n['read_at']?'covered':'gap'?>"><?=$n['read_at']?'Read':'New'?></b></div><?php endforeach;?><?php if(!$notifications):?><div class="inline-empty"><strong>No notifications</strong></div><?php endif;?></article></section></main></body></html>
